/**
 * Официальные расписания времени намаза ЦДУМ России для всех опубликованных городов.
 * Формат каждого дня: "Фаджр,Восход,Зухр,Аср,Магриб,Иша", дни разделены "|"
 */

function buildLookup(
  compactByMonth: Record<number, string>
): Record<string, [string, string, string, string, string, string]> {
  const map: Record<string, [string, string, string, string, string, string]> = {};
  for (const [mStr, daysStr] of Object.entries(compactByMonth)) {
    const m = Number(mStr);
    const days = daysStr.split("|");
    days.forEach((dStr, idx) => {
      const parts = dStr.split(",") as [string, string, string, string, string, string];
      map[`${m}_${idx + 1}`] = parts;
    });
  }
  return map;
}

