const PARSED_ROSTOV_BY_MONTH_DAY = buildLookup(ROSTOV_COMPACT_BY_MONTH);

export function getRostovDayTimes(
  month: number,
  day: number
): [string, string, string, string, string, string] {
  return (
    PARSED_ROSTOV_BY_MONTH_DAY[`${month}_${day}`] ||
    PARSED_ROSTOV_BY_MONTH_DAY[`${month}_1`] || [
      "05:00",
      "07:00",
      "12:30",
      "15:30",
      "18:00",
      "19:30",
    ]
  );
}

